def isMstUnique(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    es = sorted(edges, key=lambda e: e[2])
    i = 0
    m = len(es)
    while i < m:
        j = i
        while j < m and es[j][2] == es[i][2]:
            j += 1
        candidates = 0
        for k in range(i, j):
            if find(es[k][0]) != find(es[k][1]):
                candidates += 1
        added = 0
        for k in range(i, j):
            ra, rb = find(es[k][0]), find(es[k][1])
            if ra != rb:
                parent[ra] = rb
                added += 1
        if added != candidates:
            return False
        i = j
    return True
